
.row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--c-border);
}

.row-label {
  width: 24px;
  color: var(--c-primary);
  font-size: 14px;
  text-align: center;
  flex-shrink: 0;
}

.row-content {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  flex-wrap: wrap;
}

.stat-block {
  display: flex;
  align-items: center;
  gap: 5px;
}

.stat-icon {
  color: var(--c-text-muted);
  font-size: 11px;
  width: 16px;
  text-align: center;
}

.stat-label {
  color: var(--c-text-muted);
  font-size: 11px;
  white-space: nowrap;
}

.stat-value {
  font-weight: 600;
  font-size: 13px;
}

.realm-value {
  color: var(--c-primary);
  font-family: var(--font-display);
  letter-spacing: 1px;
}

.stat-divider {
  width: 1px;
  height: 16px;
  background: var(--c-border);
  margin: 0 2px;
}

.aptitude-supreme { color: var(--c-primary); }
.aptitude-high { color: #7ec8e3; }
.aptitude-mid { color: var(--c-text); }
.aptitude-unknown { color: var(--c-text-muted); }

.spirit-badge {
  padding: 1px 8px;
  border-radius: 3px;
  background: var(--c-bg-card);
  border: 1px solid var(--c-jade);
  color: var(--c-jade-light);
  font-size: 12px;
}
