
.row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--c-border);
}

.row-label {
  width: 24px;
  color: var(--c-affection);
  font-size: 14px;
  text-align: center;
  flex-shrink: 0;
  padding-top: 2px;
}

.row-content {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
}

.bar-group {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.bar-header {
  display: flex;
  align-items: center;
  gap: 6px;
}

.bar-label {
  color: var(--c-text-muted);
  font-size: 11px;
}

.bar-value {
  font-weight: 700;
  font-size: 14px;
  font-family: var(--font-display);
}

.bar-tag {
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 3px;
  background: var(--c-bg-card);
  margin-left: auto;
}

/* 好感度颜色梯度 */
.tier-gold { color: var(--c-primary); }
.tier-pink { color: var(--c-affection); }
.tier-orange { color: #e8a050; }
.tier-red { color: var(--c-danger); }
.tier-purple { color: var(--c-mind); }

.bar-track {
  position: relative;
  height: 10px;
  border-radius: 5px;
  background: var(--c-bg-deep);
  border: 1px solid var(--c-border);
  overflow: visible;
}

.bar-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  border-radius: 4px;
  transition: width 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.bar-fill-affection {
  background: linear-gradient(90deg, #c0392b, #e8a050 30%, #e891b4 60%, #d4a853);
}

.bar-fill-corruption {
  background: linear-gradient(90deg, #5a1a2a, #8b1a2b 30%, #6b1a5a 70%, #2a0a3a);
}

.bar-stage-mark {
  position: absolute;
  top: -5px;
  font-size: 9px;
  color: var(--c-text-muted);
  transform: translateX(-50%);
  z-index: 1;
  cursor: default;
}
