
.expand-section {
  border-top: 1px solid var(--c-border);
}

.expand-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  width: 100%;
  padding: 6px;
  background: transparent;
  border: none;
  color: var(--c-text-muted);
  font-size: 11px;
  font-family: var(--font-body);
  cursor: pointer;
  transition: color 0.2s;
}

.expand-toggle:hover {
  color: var(--c-text);
}

.tabs-area {
  border-top: 1px solid var(--c-border);
  animation: slideDown 0.3s ease;
}

@keyframes slideDown {
  from { opacity: 0; max-height: 0; }
  to { opacity: 1; max-height: 600px; }
}

.tab-nav {
  display: flex;
  border-bottom: 1px solid var(--c-border);
}

.tab-btn {
  flex: 1;
  padding: 7px 4px;
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--c-text-muted);
  font-size: 11px;
  font-family: var(--font-body);
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

.tab-btn:hover {
  color: var(--c-text);
  background: var(--c-bg-card);
}

.tab-btn.active {
  color: var(--c-primary);
  border-bottom-color: var(--c-primary);
}

.tab-content {
  padding: 8px;
  max-height: 280px;
  overflow-y: auto;
}

.tab-pane {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.empty-notice {
  text-align: center;
  color: var(--c-text-muted);
  font-size: 12px;
  padding: 14px 0;
  font-style: italic;
}

.entry-card {
  background: var(--c-bg-card);
  border: 1px solid var(--c-border);
  border-radius: 4px;
  padding: 8px 10px;
}

.entry-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}

.entry-name {
  font-weight: 600;
  font-size: 12px;
  color: var(--c-text);
}

.entry-type,
.entry-level,
.entry-count,
.entry-location {
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 3px;
  background: var(--c-bg-deep);
  color: var(--c-text-muted);
}

.entry-difficulty {
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 3px;
  margin-left: auto;
}

.diff-简单 { background: #1a3a1a; color: var(--c-jade-light); }
.diff-普通 { background: #2a2a1a; color: var(--c-primary); }
.diff-困难 { background: #3a1a1a; color: var(--c-danger); }
.diff-致命 { background: #2a0a1a; color: #c0392b; }

.entry-body {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.entry-desc {
  font-size: 11px;
  color: var(--c-text-muted);
  flex: 1;
}

.entry-proficiency {
  font-size: 10px;
  color: var(--c-primary);
}

.entry-item .entry-header {
  justify-content: space-between;
}

.quest-goal,
.quest-reward {
  font-size: 11px;
  color: var(--c-text);
  display: flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}

.quest-goal i { color: var(--c-danger); font-size: 9px; }
.quest-reward i { color: var(--c-primary); font-size: 9px; }

.quest-intro {
  font-size: 11px;
  color: var(--c-text-muted);
  font-style: italic;
  width: 100%;
}

.entry-event .entry-header {
  justify-content: space-between;
}
